// Des: Detect page charset and convert body to UTF-8
// Flo: BOM > header charset > meta charset in first 2 KB > label to Cset > convert to UTF-8 > fix bad bytes
// I/O: Content-Type text + body bytes (fetcher) > owned UTF-8 bytes (caller frees)
// ===================================================================
const std = @import("std"); const mem = std.mem;
const CF = .{ .scan = 2048, .repl = "\xEF\xBF\xBD", .w125 = [32]u21{ 0x20AC, 0x81, 0x201A, 0x0192, 0x201E, 0x2026, 0x2020, 0x2021, 0x02C6, 0x2030, 0x0160, 0x2039, 0x0152, 0x8D, 0x017D, 0x8F, 0x90, 0x2018, 0x2019, 0x201C, 0x201D, 0x2022, 0x2013, 0x2014, 0x02DC, 0x2122, 0x0161, 0x203A, 0x0153, 0x9D, 0x017E, 0x0178 } };
pub const Cset = enum { utf8, w1252, utf16le, utf16be, unkn };
fn labl(text: []const u8) Cset { const tabl = [_]struct { name: []const u8, sets: Cset }{ .{ .name = "utf-8", .sets = .utf8 }, .{ .name = "utf8", .sets = .utf8 }, .{ .name = "iso-8859-1", .sets = .w1252 }, .{ .name = "latin1", .sets = .w1252 }, .{ .name = "windows-1252", .sets = .w1252 }, .{ .name = "cp1252", .sets = .w1252 }, .{ .name = "us-ascii", .sets = .w1252 }, .{ .name = "ascii", .sets = .w1252 }, .{ .name = "utf-16le", .sets = .utf16le }, .{ .name = "utf-16be", .sets = .utf16be } }; for (tabl) |item| if (std.ascii.eqlIgnoreCase(text, item.name)) return item.sets; return .unkn; }
fn tokn(text: []const u8, key: []const u8) ?[]const u8 { var indx: usize = 0; while (indx + key.len <= text.len) : (indx += 1) { if (!std.ascii.eqlIgnoreCase(text[indx .. indx + key.len], key)) continue; var beg = indx + key.len; while (beg < text.len and (text[beg] == ' ' or text[beg] == '"' or text[beg] == '\'')) beg += 1; var endz = beg; while (endz < text.len and text[endz] != '"' and text[endz] != '\'' and text[endz] != ';' and text[endz] != ' ' and text[endz] != '>' and text[endz] != '/') endz += 1; if (endz > beg) return text[beg..endz]; } return null; }
pub fn charFind(ctyp: []const u8, body: []const u8) Cset { if (mem.startsWith(u8, body, "\xEF\xBB\xBF")) return .utf8; if (mem.startsWith(u8, body, "\xFF\xFE")) return .utf16le; if (mem.startsWith(u8, body, "\xFE\xFF")) return .utf16be; if (tokn(ctyp, "charset=")) |name| return labl(name); if (tokn(body[0..@min(body.len, CF.scan)], "charset=")) |name| return labl(name); return .utf8; }
fn emit(allo: std.mem.Allocator, outp: *std.ArrayList(u8), cpnt: u21) !void { var buff: [4]u8 = undefined; const lenz = std.unicode.utf8Encode(cpnt, &buff) catch return outp.appendSlice(allo, CF.repl); try outp.appendSlice(allo, buff[0..lenz]); }
fn utf8Fix(allo: std.mem.Allocator, body: []const u8) ![]u8 { var outp: std.ArrayList(u8) = .empty; errdefer outp.deinit(allo); try outp.ensureTotalCapacity(allo, body.len); var indx: usize = 0; while (indx < body.len) { const lenz = std.unicode.utf8ByteSequenceLength(body[indx]) catch { try outp.appendSlice(allo, CF.repl); indx += 1; continue; }; if (indx + lenz > body.len or !std.unicode.utf8ValidateSlice(body[indx .. indx + lenz])) { try outp.appendSlice(allo, CF.repl); indx += 1; continue; } try outp.appendSlice(allo, body[indx .. indx + lenz]); indx += lenz; } return outp.toOwnedSlice(allo); }
pub fn utf8Conv(allo: std.mem.Allocator, sets: Cset, body: []const u8) ![]u8 { switch (sets) { .utf8 => { const skip: usize = if (mem.startsWith(u8, body, "\xEF\xBB\xBF")) 3 else 0; return utf8Fix(allo, body[skip..]); }, .w1252 => { var outp: std.ArrayList(u8) = .empty; errdefer outp.deinit(allo); for (body) |byte| try emit(allo, &outp, if (byte >= 0x80 and byte <= 0x9F) CF.w125[byte - 0x80] else byte); return outp.toOwnedSlice(allo); }, .utf16le, .utf16be => { var unit: std.ArrayList(u16) = .empty; defer unit.deinit(allo); const skip: usize = if (body.len >= 2 and (mem.startsWith(u8, body, "\xFF\xFE") or mem.startsWith(u8, body, "\xFE\xFF"))) 2 else 0; var indx: usize = skip; while (indx + 1 < body.len) : (indx += 2) { const pair = [2]u8{ body[indx], body[indx + 1] }; try unit.append(allo, mem.readInt(u16, &pair, if (sets == .utf16le) .little else .big)); } return std.unicode.utf16LeToUtf8Alloc(allo, unit.items) catch return error.CharBad; }, .unkn => { if (std.unicode.utf8ValidateSlice(body)) return allo.dupe(u8, body); return error.CharUnsupported; } } }
